INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'wildlife', 'n.', '/ˈwaɪldlaɪf/', '野生动物;野生生物', 'We must work together for wildlife protection.', '我们必须共同努力保护野生动物。', 'Wildlife Protection', 1, 0, 'senior', 'wordlist', 'required2', 'U2', 'wildlife protection', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'protection', 'n.', '/prəˈtekʃn/', '保护;防护', 'The government placed the antelope under national protection.', '政府把羚羊置于国家保护之下。', 'Wildlife Protection', 2, 0, 'senior', 'wordlist', 'required2', 'U2', 'under national protection', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'endanger', 'v.', '/ɪnˈdeɪndʒə(r)/', '使遭受危险;危害', 'Hunting and pollution endanger many wild species.', '捕猎和污染危害许多野生物种。', 'Wildlife Protection', 3, 0, 'senior', 'wordlist', 'required2', 'U2', 'endanger wildlife', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'endangered', 'adj.', '/ɪnˈdeɪndʒəd/', '濒危的;有灭绝危险的', 'The panda is no longer an endangered species today.', '如今熊猫不再是濒危物种了。', 'Wildlife Protection', 4, 0, 'senior', 'wordlist', 'required2', 'U2', 'an endangered species', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'species', 'n.', '/ˈspiːʃiːz/', '物种;种类', 'Between 150 and 200 species become extinct every day.', '每天有150到200个物种灭绝。', 'Wildlife Protection', 5, 0, 'senior', 'wordlist', 'required2', 'U2', 'a rare species', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extinct', 'adj.', '/ɪkˈstɪŋkt/', '已灭绝的;不再存在的', 'Many animals have already become extinct because of hunting.', '许多动物已因捕猎而灭绝。', 'Wildlife Protection', 6, 0, 'senior', 'wordlist', 'required2', 'U2', 'become extinct', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extinction', 'n.', '/ɪkˈstɪŋkʃn/', '灭绝;消亡', 'We must save this species from extinction.', '我们必须使这一物种免于灭绝。', 'Wildlife Protection', 7, 0, 'senior', 'wordlist', 'required2', 'U2', 'save sth from extinction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'habitat', 'n.', '/ˈhæbɪtæt/', '(动植物的)生活环境;栖息地', 'Their habitat is getting smaller as new roads are built.', '随着新路修建,它们的栖息地越来越小。', 'Wildlife Protection', 8, 0, 'senior', 'wordlist', 'required2', 'U2', 'habitat loss', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reserve', 'n./v.', '/rɪˈzɜːv/', '(动植物)保护区;储备;预订;保留', 'The nature reserve is a shelter for wild animals and plants.', '这个自然保护区是野生动植物的庇护所。', 'Wildlife Protection', 9, 0, 'senior', 'wordlist', 'required2', 'U2', 'a nature reserve', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'antelope', 'n.', '/ˈæntɪləʊp/', '羚;羚类动物', 'We came here to observe the antelope on the plain.', '我们来这里观察平原上的羚羊。', 'Wildlife Protection', 10, 0, 'senior', 'wordlist', 'required2', 'U2', 'a herd of antelope', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'herd', 'n.', '/hɜːd/', '牧群;兽群', 'We can just make out a herd of graceful animals.', '我们勉强能看清一群优雅的动物。', 'Wildlife Protection', 11, 0, 'senior', 'wordlist', 'required2', 'U2', 'a herd of deer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'observe', 'v.', '/əbˈzɜːv/', '观察(到);注视;遵守', 'Scientists watched over the antelopes to observe their habits.', '科学家们看护着羚羊以观察它们的习性。', 'Wildlife Protection', 12, 0, 'senior', 'wordlist', 'required2', 'U2', 'observe wildlife', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hunt', 'v./n.', '/hʌnt/', '打猎;追捕;搜寻', 'Hunters used to hunt antelopes for their valuable fur.', '猎人过去为珍贵的毛皮捕猎羚羊。', 'Wildlife Protection', 13, 0, 'senior', 'wordlist', 'required2', 'U2', 'hunt for fur', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hunter', 'n.', '/ˈhʌntə(r)/', '猎人', 'Illegal hunters shot the animals to make profits.', '非法猎人射杀这些动物以牟利。', 'Wildlife Protection', 14, 0, 'senior', 'wordlist', 'required2', 'U2', 'illegal hunters', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'illegal', 'adj.', '/ɪˈliːɡl/', '不合法的;非法的', 'The illegal trade in animal fur must be stopped.', '动物毛皮的非法交易必须被制止。', 'Wildlife Protection', 15, 0, 'senior', 'wordlist', 'required2', 'U2', 'the illegal trade', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'illegally', 'adv.', '/ɪˈliːɡəli/', '不合法地;非法地', 'The antelopes were hunted illegally for their fur.', '羚羊为其毛皮被非法捕猎。', 'Wildlife Protection', 16, 0, 'senior', 'wordlist', 'required2', 'U2', 'be hunted illegally', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fur', 'n.', '/fɜː(r)/', '毛(皮);毛皮衣服', 'Please do not buy goods made from animal fur.', '请不要购买用动物毛皮制成的商品。', 'Wildlife Protection', 17, 0, 'senior', 'wordlist', 'required2', 'U2', 'valuable fur', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'shoot', 'v.', '/ʃuːt/', '射杀;射伤;发射', 'Hunters were shooting antelopes to make money.', '猎人们为了赚钱射杀羚羊。', 'Wildlife Protection', 18, 0, 'senior', 'wordlist', 'required2', 'U2', 'shoot animals', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'profit', 'n.', '/ˈprɒfɪt/', '利润;利益;好处', 'Some people kill wild animals only to make profits.', '有些人杀害野生动物只为牟利。', 'Wildlife Protection', 19, 0, 'senior', 'wordlist', 'required2', 'U2', 'make profits', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'threat', 'n.', '/θret/', '威胁;恐吓', 'These animals face a serious threat from hunters.', '这些动物面临来自猎人的严重威胁。', 'Wildlife Protection', 20, 0, 'senior', 'wordlist', 'required2', 'U2', 'a serious threat', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'threaten', 'v.', '/ˈθretn/', '威胁;危及;扬言', 'Human activities are threatening animals and plants.', '人类活动正威胁着动植物。', 'Wildlife Protection', 21, 0, 'senior', 'wordlist', 'required2', 'U2', 'threaten wildlife', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'attack', 'v./n.', '/əˈtæk/', '攻击;抨击;袭击', 'Volunteers watched over the antelopes to keep them safe from attacks.', '志愿者看护羚羊,使它们免遭袭击。', 'Wildlife Protection', 22, 0, 'senior', 'wordlist', 'required2', 'U2', 'safe from attacks', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'measure', 'n./v.', '/ˈmeʒə(r)/', '措施;方法;测量;估量', 'What measures are being taken to help the elephants?', '正在采取什么措施来帮助大象?', 'Wildlife Protection', 23, 0, 'senior', 'wordlist', 'required2', 'U2', 'take measures', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'effective', 'adj.', '/ɪˈfektɪv/', '有效的;生效的', 'The measures proved to be very effective.', '这些措施被证明非常有效。', 'Wildlife Protection', 24, 0, 'senior', 'wordlist', 'required2', 'U2', 'an effective measure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'recover', 'v.', '/rɪˈkʌvə(r)/', '恢复;康复;找回', 'The antelope population has recovered in recent years.', '近年来羚羊数量已经恢复。', 'Wildlife Protection', 25, 0, 'senior', 'wordlist', 'required2', 'U2', 'recover from danger', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'remove', 'v.', '/rɪˈmuːv/', '去除;移开;脱去', 'The antelope was removed from the endangered species list.', '羚羊已从濒危物种名单中移除。', 'Wildlife Protection', 26, 0, 'senior', 'wordlist', 'required2', 'U2', 'remove from the list', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'intend', 'v.', '/ɪnˈtend/', '打算;计划;想要', 'The government does not intend to stop the protection.', '政府不打算停止这项保护。', 'Wildlife Protection', 27, 0, 'senior', 'wordlist', 'required2', 'U2', 'intend to do', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'exist', 'v.', '/ɪɡˈzɪst/', '存在;生存', 'We must learn to exist in harmony with nature.', '我们必须学会与自然和谐共存。', 'Wildlife Protection', 28, 0, 'senior', 'wordlist', 'required2', 'U2', 'exist in harmony', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'harmony', 'n.', '/ˈhɑːməni/', '和谐;融洽', 'Humans and animals should live in harmony.', '人类和动物应当和谐相处。', 'Wildlife Protection', 29, 0, 'senior', 'wordlist', 'required2', 'U2', 'in harmony with', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reduce', 'v.', '/rɪˈdjuːs/', '减少;降低', 'We should reduce the threat to wildlife.', '我们应当减少对野生动物的威胁。', 'Wildlife Protection', 30, 0, 'senior', 'wordlist', 'required2', 'U2', 'reduce the threat', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'alarm', 'n./v.', '/əˈlɑːm/', '惊恐;警报;使惊恐', 'Wildlife is dying out at an alarming rate.', '野生动物正以惊人的速度消失。', 'Wildlife Protection', 31, 0, 'senior', 'wordlist', 'required2', 'U2', 'at an alarming rate', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'alarming', 'adj.', '/əˈlɑːmɪŋ/', '惊人的;使人惊恐的', 'The report gives some alarming facts about extinction.', '这份报告给出了一些关于灭绝的惊人事实。', 'Wildlife Protection', 32, 0, 'senior', 'wordlist', 'required2', 'U2', 'an alarming rate', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'aware', 'adj.', '/əˈweə(r)/', '知道的;意识到的', 'We must make people aware of the problem.', '我们必须让人们意识到这个问题。', 'Wildlife Protection', 33, 0, 'senior', 'wordlist', 'required2', 'U2', 'be aware of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'concern', 'v./n.', '/kənˈsɜːn/', '涉及;使担忧;担心;关心', 'I''m concerned about the African elephants.', '我很担心非洲象。', 'Wildlife Protection', 34, 0, 'senior', 'wordlist', 'required2', 'U2', 'express concern', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'concerned', 'adj.', '/kənˈsɜːnd/', '担心的;关切的', 'Many people are concerned about wildlife protection.', '许多人关心野生动物保护。', 'Wildlife Protection', 35, 0, 'senior', 'wordlist', 'required2', 'U2', 'concerned about', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pressure', 'n.', '/ˈpreʃə(r)/', '压力;要求', 'The authorities are under pressure to build animal parks.', '当局承受着修建动物园区的压力。', 'Wildlife Protection', 36, 0, 'senior', 'wordlist', 'required2', 'U2', 'under pressure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'authority', 'n.', '/ɔːˈθɒrəti/', '官方;当局;权威', 'The authorities tell people not to buy elephant products.', '当局告诉人们不要购买大象制品。', 'Wildlife Protection', 37, 0, 'senior', 'wordlist', 'required2', 'U2', 'the local authority', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'adapt', 'v.', '/əˈdæpt/', '适应;使适应;改编', 'It is difficult for elephants to adapt to the changes.', '大象很难适应这些变化。', 'Wildlife Protection', 38, 0, 'senior', 'wordlist', 'required2', 'U2', 'adapt to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'creature', 'n.', '/ˈkriːtʃə(r)/', '生物;动物', 'The world must protect these beautiful creatures.', '世界必须保护这些美丽的生物。', 'Wildlife Protection', 39, 0, 'senior', 'wordlist', 'required2', 'U2', 'beautiful creatures', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'average', 'n./adj.', '/ˈævərɪdʒ/', '平均数;平均的;普通的', 'Many elephants are killed on average every day.', '平均每天有许多大象被杀害。', 'Wildlife Protection', 40, 0, 'senior', 'wordlist', 'required2', 'U2', 'on average', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sacred', 'adj.', '/ˈseɪkrɪd/', '神圣的;受尊敬的', 'To Zhaxi, the land is sacred and worth protecting.', '对扎西来说,这片土地是神圣的、值得保护的。', 'Wildlife Protection', 41, 0, 'senior', 'wordlist', 'required2', 'U2', 'sacred land', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'remind', 'v.', '/rɪˈmaɪnd/', '提醒;使想起', 'The antelopes remind me of the danger they were in.', '这些羚羊使我想起它们曾面临的危险。', 'Wildlife Protection', 42, 0, 'senior', 'wordlist', 'required2', 'U2', 'remind sb of sth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'poster', 'n.', '/ˈpəʊstə(r)/', '海报;招贴画', 'We made a poster to call for wildlife protection.', '我们制作了一张海报呼吁保护野生动物。', 'Wildlife Protection', 43, 0, 'senior', 'wordlist', 'required2', 'U2', 'make a poster', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'emotion', 'n.', '/ɪˈməʊʃn/', '感情;情感;情绪', 'A good poster can stir up strong emotions in people.', '一张好的海报能激起人们强烈的情感。', 'Wildlife Protection', 44, 0, 'senior', 'wordlist', 'required2', 'U2', 'stir up emotions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unusual', 'adj.', '/ʌnˈjuːʒuəl/', '不寻常的;特别的', 'Write a title that is simple and unusual.', '写一个简洁而不寻常的标题。', 'Wildlife Protection', 45, 0, 'senior', 'wordlist', 'required2', 'U2', 'an unusual title', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'due', 'adj.', '/djuː/', '由于;因为;应得的', 'Living spaces for wildlife are reduced due to the cutting of trees.', '由于砍伐树木,野生动物的生存空间在减少。', 'Wildlife Protection', 46, 0, 'senior', 'wordlist', 'required2', 'U2', 'due to', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.01', '①肯定句 am/is/are being + 过去分词', 'A2', 10, '必修二 U2 — 主语是动作的承受者、动作此刻正在被进行时,用 am/is/are being + 过去分词。单数主语用 is being done,复数主语用 are being done。', 1, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.02', '②否定与一般疑问(isn''t/aren''t being done; Is/Are ... being done?)', 'A2', 10, '必修二 U2 — 否定在 be 后加 not:isn''t/aren''t being done;一般疑问把 be 提到主语前:Is/Are + 主语 + being + 过去分词?', 2, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u2.03', '③主动↔被动转换 · by 短语 · 与一般现在被动(is done)对照', 'A2', 10, '必修二 U2 — 主动句变被动时,正在进行的动作用 are being done,by 引出动作执行者;区分''此刻正在被做''(is being done)与''经常被做/客观事实''(is done)。', 3, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
