INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'The keepers are feeding the orphan elephants. → The orphan elephants ____ by the keepers now.', 'are feeding', 'feed', 'have fed', 'are being fed', 'D', '主动改被动、动作正在进行 → are being fed by …。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'At this very moment, a poster ____ by the students to call for protection.', 'is being designed', 'is designing', 'designs', 'has designed', 'A', '单数主语 poster、动作正在进行 → is being designed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'People are selling wild ducks at the market. → Wild ducks ____ at the market by some people.', 'are selling', 'are being sold', 'sell', 'have sold', 'B', '主动改被动、动作正在进行 → are being sold by …。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Shark fins ____ in many restaurants every day, though no shark is being killed in this bay now.', 'are being served', 'were served', 'are served', 'have served', 'C', '''每天(经常)被供应''是反复事实 → 一般现在被动 are served。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'The club members are cleaning up the habitats. → The habitats ____ up by the members right now.', 'are cleaning', 'clean', 'have cleaned', 'are being cleaned', 'D', '主动改被动、动作正在进行 → are being cleaned by …。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Look — a new smell ____ near the cameras to attract the shy wolverines.', 'is being sent out', 'is sending out', 'sends out', 'has sent out', 'A', '单数主语 smell、动作正在进行 → is being sent out。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'A team is carrying out a plan to save the tigers. → A plan ____ out by a team at present.', 'is carrying', 'is being carried', 'carries', 'has carried', 'B', '主动改被动、动作正在进行 → is being carried out by …。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Wild animals ____ under national protection by law, and right now new gates are being added.', 'are being placed', 'were placed', 'are placed', 'have placed', 'C', '''依法(一直)被置于保护之下''是客观规定 → 一般现在被动 are placed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Local students are recording the bird songs. → The bird songs ____ by local students now.', 'are recording', 'record', 'have recorded', 'are being recorded', 'D', '主动改被动、动作正在进行 → are being recorded by …。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'At the moment, the injured deer ____ to a safer place by the rangers.', 'is being moved', 'is moving', 'moves', 'has moved', 'A', '单数主语 deer(此处指一只)、动作正在进行 → is being moved。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Hunters are shooting the antelopes for their fur. → The antelopes ____ for their fur by hunters.', 'are shooting', 'are being shot', 'shoot', 'have shot', 'B', '主动改被动、动作正在进行 → are being shot by …。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'Pandas ____ in this base all year round, but no cub is being moved out this week.', 'are being protected', 'were protected', 'are protected', 'have protected', 'C', '''一年到头(经常)被保护''是惯常事实 → 一般现在被动 are protected。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U2' AND code='u2.03'), 'The authorities are reducing the living spaces by mistake. → The living spaces ____ by the authorities now.', 'are reducing', 'reduce', 'have reduced', 'are being reduced', 'D', '主动改被动、动作正在进行 → are being reduced by …。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Day with the Antelopes', 'The air was thin, and we had to rest several times on the short hike from camp. On the plain in front of us, we could just make out a herd of graceful animals. This was why we had come here: to observe the Tibetan antelopes. Watching them move slowly across the green grass, I was struck by their beauty. My guide, a villager named Zhaxi, works at a nature reserve that gives shelter to the wild animals of the area. To him, the land is sacred, and protecting the wildlife is a way of life. He told me that during the 1980s and 1990s the antelope population dropped sharply, because hunters were shooting the animals to make profits and their living spaces were becoming smaller. To save the species, the government placed it under national protection, and volunteers watched over the herds day and night. Thanks to these measures, the population has recovered, and the antelope is no longer in danger. Yet Zhaxi still worries, for the threats have not completely disappeared.', '记叙·藏羚羊保护区见闻', 173, '[{"q":"Why did the writer travel to the plain?","answer":"A","options":["To watch and study the Tibetan antelopes.","To go shopping in a nearby town.","To hunt animals for their fur.","To build a new road across the grass."],"explanation":"原文 ''to observe the Tibetan antelopes'' 的转述。"},{"q":"What caused the antelope population to fall in the 1980s and 1990s?","answer":"B","options":["Too much rain on the plain.","Hunting for profit and the loss of living space.","A lack of interest from the government.","The animals moving to another country."],"explanation":"原文 ''hunters were shooting the animals to make profits and their living spaces were becoming smaller'' 的概括。"},{"q":"How does Zhaxi feel about the antelopes now?","answer":"A","options":["He still worries because dangers remain.","He thinks the work is completely finished.","He no longer cares about them.","He wants to start hunting them again."],"explanation":"末句 ''still worries, for the threats have not completely disappeared'' 的转述。"}]'::jsonb, '[{"word":"antelope","cn":"羚羊"},{"word":"herd","cn":"兽群"},{"word":"reserve","cn":"保护区"},{"word":"sacred","cn":"神圣的"},{"word":"recover","cn":"恢复"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Wetland Near My Home', 'When I was in primary school, there was a beautiful wetland near my home. It was full of life, with wild birds, fish, snakes and countless insects. My friends and I often went there to watch the birds and study them, and it was an interesting place for all of us. But things have begun to change in recent years. Small birds are being caught with nets, and wild ducks are being sold at the food market in town. Fish and snakes are being killed for food in some restaurants. Even worse, the wetland itself is being destroyed. Some parts are now being covered with new houses, and there is rubbish everywhere. The water is being polluted a little more every day. Whenever I go back, I feel very worried, because the place I loved as a child is slowly disappearing. I keep asking myself one question: what can ordinary people like us actually do to save it before it is too late?', '记叙·家乡湿地的变化', 163, '[{"q":"What was the wetland like when the writer was a child?","answer":"B","options":["It was empty and lifeless.","It was full of birds, fish and insects.","It was already covered with houses.","It was used only as a market."],"explanation":"原文 ''full of life, with wild birds, fish, snakes and countless insects'' 的转述。"},{"q":"Which of the following is happening to the wetland now?","answer":"C","options":["Its water is becoming cleaner each day.","More wild animals are moving in to live there.","Birds and ducks are being caught and sold.","The town has turned it into a new reserve."],"explanation":"原文 ''Small birds are being caught… wild ducks are being sold'' 的概括。"},{"q":"How does the writer feel about these changes?","answer":"D","options":["Proud and satisfied.","Bored and uninterested.","Calm and hopeful.","Worried and anxious to help."],"explanation":"末段 ''feel very worried… what can ordinary people like us actually do'' 的转述。"}]'::jsonb, '[{"word":"wetland","cn":"湿地"},{"word":"insect","cn":"昆虫"},{"word":"destroy","cn":"破坏"},{"word":"pollute","cn":"污染"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'What Are We Doing to Our Planet?', 'Our planet is changing fast, and not always for the better. Wildlife is dying out at an alarming rate. Experts say that between 150 and 200 species become extinct every single day. This mass extinction is mainly caused by hunting, the loss of habitats and pollution. Once a species has gone, it can never come back, and the whole web of life around it grows weaker. The good news is that more and more people are beginning to understand the danger. Posters, films and online videos are being used to make ordinary people aware of the problem. When buyers stop wanting animal products, the killing slows down too. That is why one famous slogan says simply, ''When the buying stops, the killing can too.'' Saving wildlife is not only the job of scientists or governments. Each of us can make a difference by refusing to buy goods made from wild animals, and by sharing what we know with our friends and family. Change really does begin with you.', '说明·物种灭绝与公众觉醒', 168, '[{"q":"According to the passage, what mainly causes the mass extinction?","answer":"A","options":["Hunting, habitat loss and pollution.","Cold weather and heavy snow.","A shortage of zoos and parks.","Too many nature reserves."],"explanation":"原文 ''mainly caused by hunting, the loss of habitats and pollution'' 的转述。"},{"q":"What does the writer say happens when buyers stop wanting animal products?","answer":"B","options":["More species become extinct.","The killing of animals slows down.","Hunters earn larger profits.","Reserves have to be closed."],"explanation":"原文 ''When buyers stop wanting animal products, the killing slows down too'' 的转述。"},{"q":"What is the writer''s main message in the last part?","answer":"C","options":["Only scientists can solve the problem.","Buying animal goods is harmless.","Ordinary individuals can also help protect wildlife.","The danger has already disappeared."],"explanation":"末段 ''Each of us can make a difference… Change really does begin with you'' 的概括。"}]'::jsonb, '[{"word":"die out","cn":"灭亡;逐渐消失"},{"word":"extinct","cn":"灭绝的"},{"word":"mass extinction","cn":"大规模灭绝"},{"word":"aware","cn":"意识到的"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Work of the WWF', 'The World Wide Fund for Nature, often called the WWF, is one of the best-known wildlife organisations in the world. Its task is to protect the many kinds of plants and animals that share our planet with us. The WWF believes that most people do not really want to harm wild creatures. The trouble is that many of them simply do not understand how serious the situation has become. So the group works hard to share clear information and to stir up public interest in the welfare of nature. It hopes that, once people learn the facts, they will stop buying animal products and start looking for better solutions. Many wild species cannot easily adapt to the rapid changes brought about by modern life, so they need our help to survive. Around the world, the WWF supports nature reserves, fights against the illegal animal trade, and teaches young people why wildlife matters. Step by step, it is trying to build a future in which humans and animals can live side by side.', '说明·世界自然基金会', 172, '[{"q":"What is the main task of the WWF?","answer":"D","options":["To sell products made from wild animals.","To build large modern cities.","To stop people from visiting nature.","To protect the world''s plants and animals."],"explanation":"原文 ''protect the many kinds of plants and animals'' 的转述。"},{"q":"Why does the WWF spend so much effort sharing information?","answer":"A","options":["Because many people do not realise how serious the problem is.","Because it wants to make money quickly.","Because the law forces it to do so.","Because scientists have already solved everything."],"explanation":"原文 ''many of them simply do not understand how serious the situation has become'' 的转述。"},{"q":"What kind of future does the WWF hope to build?","answer":"B","options":["A world with no wild animals left.","A world where people and animals live together.","A world where only humans matter.","A world full of illegal animal trade."],"explanation":"末句 ''humans and animals can live side by side'' 的转述。"}]'::jsonb, '[{"word":"organisation","cn":"组织"},{"word":"welfare","cn":"福祉"},{"word":"adapt","cn":"适应"},{"word":"illegal","cn":"非法的"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Posters That Speak', 'A good poster can do something that a long report often cannot: it can touch people''s hearts in a single moment. The best wildlife posters are simple, but they stir up strong emotions. One poster shows a lonely koala beside a fallen tree, with the words, ''Don''t make paper with my home!'' Behind the joke is a serious truth: billions of trees are being cut down every year, and many animal homes are being destroyed at the same time. Another poster reminds us that all species deserve care, not only the cute and famous ones. Pandas and dolphins easily win our love, but less attractive creatures matter too, because nature needs every kind to stay healthy. When you design a poster, experts suggest a few clear steps. Choose a title that is short, interesting and a little unusual. Use one powerful image to catch the reader''s eye. Then tell the reader exactly what you want them to think and do. A poster that follows these steps can turn a quiet feeling into real action.', '说明·海报如何打动人心', 174, '[{"q":"According to the passage, what can a good poster do better than a long report?","answer":"C","options":["List every fact about an animal.","Replace the work of scientists.","Touch people''s feelings in a single moment.","Make trees grow faster."],"explanation":"原文 ''touch people''s hearts in a single moment'' 的转述。"},{"q":"Why does the writer say less attractive animals also matter?","answer":"D","options":["Because they are easy to sell.","Because they make the best pets.","Because pandas and dolphins dislike them.","Because a healthy natural world depends on every kind of creature."],"explanation":"原文 ''nature needs every kind to stay healthy'' 的转述。"},{"q":"Which step does the writer suggest when designing a poster?","answer":"A","options":["Pick one powerful image and a short, unusual title.","Use as many small pictures as possible.","Hide the message from the reader.","Choose a long and ordinary title."],"explanation":"原文 ''Choose a title that is short… Use one powerful image'' 的概括。"}]'::jsonb, '[{"word":"poster","cn":"海报"},{"word":"stir up","cn":"激起"},{"word":"emotion","cn":"情感"},{"word":"unusual","cn":"不寻常的"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Shelter for Small Friends', 'Not only endangered animals need help. Ordinary pets sometimes need it too. When families move away, they may leave a cat or a dog behind, and wounded wild birds often fall to the ground with nowhere to go. A few years ago, a group of high school students and their parents noticed how many pets had been left homeless in their town. Instead of just feeling sad, they decided to act, and together they started a small rescue shelter. Today the shelter is home to about seventy cats, fifty dogs, and a few rabbits and turtles. The young people who run it work hard to keep the place clean, feed the animals and find them new families. So far they have helped nearly two hundred animals find loving homes. The work is tiring, but the students say it is worth every minute. They welcome anyone who wants to volunteer time, money or simply love. As they like to remind visitors, what these animals need most is for someone to care.', '记叙·学生创办的动物救助站', 170, '[{"q":"What made the students decide to start the shelter?","answer":"B","options":["They wanted to earn a large profit.","They noticed that lots of homeless pets had appeared locally.","Their teacher ordered them to do it.","They were looking for a place to live."],"explanation":"原文 ''noticed how many pets had been left homeless… decided to act'' 的转述。"},{"q":"What do the young people do at the shelter?","answer":"C","options":["They sell the animals for money.","They release all the animals into the wild.","They keep the shelter tidy, feed its animals and seek new owners for them.","They keep the animals locked away from visitors."],"explanation":"原文 ''keep the place clean, feed the animals and find them new families'' 的转述。"},{"q":"According to the students, what do the animals need most?","answer":"D","options":["Expensive food and toys.","A large and famous building.","More medicine than people.","Someone who is willing to care for them."],"explanation":"末句 ''what these animals need most is for someone to care'' 的转述。"}]'::jsonb, '[{"word":"shelter","cn":"庇护所"},{"word":"wounded","cn":"受伤的"},{"word":"rescue","cn":"救助"},{"word":"volunteer","cn":"志愿(者)"}]'::jsonb, 2, 'required2', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'Saving the River Dolphin', 'The Yangtze River dolphin was once a common sight, but its numbers fell quickly. The main (1)____ was the loss of its habitat, as the river became dirty and crowded. To help the shy creature, several nature (2)____ are being built along the water. Scientists are also (3)____ for the animal in the wild, hoping to find any that are left. They know it will not be easy, because the dolphin is very (4)____ to come close to people. At the same time, the rivers are being (5)____ up by groups of volunteers, so that the water becomes safe again. Local schools (6)____ children why the dolphin matters and what they can do to help. Everyone agrees that quick action is (7)____ if the species is to survive. The work is slow, but real (8)____ is being made step by step. The team will not (9)____ up easily, for they believe the river can become a home for wildlife once more. With enough care, this beautiful animal may one day (10)____ from danger.', 173, 2, '[{"q":"1","answer":"A","options":["reason","price","noise","season"],"explanation":"the main reason 主要原因。"},{"q":"2","answer":"B","options":["markets","reserves","factories","stations"],"explanation":"nature reserves 自然保护区。"},{"q":"3","answer":"C","options":["paying","waiting","searching","asking"],"explanation":"search for 寻找。"},{"q":"4","answer":"D","options":["happy","ready","glad","afraid"],"explanation":"afraid to come close 害怕靠近。"},{"q":"5","answer":"A","options":["cleaned","sold","thrown","broken"],"explanation":"are being cleaned up 被清理。"},{"q":"6","answer":"B","options":["forget","teach","lose","sell"],"explanation":"schools teach children 学校教孩子。"},{"q":"7","answer":"C","options":["empty","late","needed","free"],"explanation":"action is needed 需要行动。"},{"q":"8","answer":"D","options":["money","noise","trouble","progress"],"explanation":"make progress 取得进步。"},{"q":"9","answer":"A","options":["give","stand","wake","look"],"explanation":"give up 放弃。"},{"q":"10","answer":"B","options":["fall","recover","leave","die"],"explanation":"recover from danger 脱离危险。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'A Plan for the Tiger', 'The South China tiger is one of the most (1)____ animals in the country. For years it has faced a serious (2)____, mainly because its forest home has been cut down and it has been hunted for its skin. To stop the tiger from becoming (3)____, a careful plan is now being carried (4)____. Scientists are working to (5)____ the number of wild tigers, and new safe areas are being set up where the cats can live in (6)____. People are also asked not to (7)____ products made from tiger parts, because buyers keep the illegal trade alive. Posters and short videos are being used to make the public (8)____ of the danger. The team knows that real change takes time, but they remain (9)____ that the tiger can be saved. If we all do our part, this powerful animal may once again move freely through the forests where it (10)____.', 151, 2, '[{"q":"1","answer":"C","options":["common","ordinary","endangered","modern"],"explanation":"endangered animals 濒危动物。"},{"q":"2","answer":"D","options":["price","noise","holiday","threat"],"explanation":"a serious threat 严重威胁。"},{"q":"3","answer":"A","options":["extinct","famous","useful","polite"],"explanation":"become extinct 灭绝。"},{"q":"4","answer":"B","options":["away","out","off","in"],"explanation":"carry out 实施。"},{"q":"5","answer":"C","options":["lose","waste","increase","drop"],"explanation":"increase the number 增加数量。"},{"q":"6","answer":"D","options":["danger","trouble","noise","peace"],"explanation":"live in peace 安宁地生活。"},{"q":"7","answer":"A","options":["buy","make","find","open"],"explanation":"not to buy products 不买制品。"},{"q":"8","answer":"B","options":["tired","aware","afraid","proud"],"explanation":"make the public aware 使公众意识到。"},{"q":"9","answer":"C","options":["angry","sorry","hopeful","bored"],"explanation":"remain hopeful 保持希望。"},{"q":"10","answer":"D","options":["sells","leaves","fails","belongs"],"explanation":"where it belongs 它属于的地方。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'Our Birdwatching Club', 'Every Saturday morning, our birdwatching club meets in the park. We get up early to (1)____ for wild birds before the streets become busy. I always bring my (2)____, so that we can see the birds clearly from far away. My friend carries a field (3)____, which we use to look up the names of the birds we (4)____. Our club does more than just watch. We clean up the (5)____ where the birds live, build feeders so they have enough (6)____, and put paper cut-outs on windows so that birds do not (7)____ into the glass. These small actions help to (8)____ the birds in our neighbourhood. At first I joined only for fun, but now I really (9)____ how wonderful these little creatures are. Caring for them has changed the way I (10)____ at nature, and I hope more young people will join us soon.', 147, 2, '[{"q":"1","answer":"A","options":["search","pay","wait","ask"],"explanation":"search for 寻找。"},{"q":"2","answer":"B","options":["tickets","binoculars","books","boxes"],"explanation":"binoculars 双筒望远镜。"},{"q":"3","answer":"C","options":["price","noise","guide","season"],"explanation":"field guide 图鉴。"},{"q":"4","answer":"D","options":["sell","throw","lose","see"],"explanation":"the birds we see 我们看到的鸟。"},{"q":"5","answer":"A","options":["habitats","markets","factories","stations"],"explanation":"clean up the habitats 清理栖息地。"},{"q":"6","answer":"B","options":["money","food","noise","paper"],"explanation":"enough food 足够食物。"},{"q":"7","answer":"C","options":["sleep","sing","crash","swim"],"explanation":"crash into the glass 撞上玻璃。"},{"q":"8","answer":"D","options":["sell","harm","leave","protect"],"explanation":"protect the birds 保护鸟类。"},{"q":"9","answer":"A","options":["appreciate","forget","waste","lose"],"explanation":"appreciate 欣赏。"},{"q":"10","answer":"B","options":["sell","look","throw","buy"],"explanation":"look at nature 看待自然。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'Concern for the Elephants', 'I am very (1)____ about the African elephants. These large animals are being (2)____ for their tusks, and at the same time their habitat is getting (3)____ as forests are cut down. Because elephants need huge living (4)____, it is very hard for them to (5)____ to such fast changes. To help them, the authorities are under (6)____ to build special parks and to tell people not to (7)____ elephant products. Reserves are being created where the animals can live in (8)____. Of course, no plan will (9)____ overnight, but every step counts. If buyers around the world lose interest in ivory, the killing will slow down too. That is why teaching the public is just as (10)____ as building reserves. Working together, we can give these gentle giants a real chance to survive.', 134, 2, '[{"q":"1","answer":"C","options":["happy","proud","concerned","bored"],"explanation":"be concerned about 担心。"},{"q":"2","answer":"D","options":["fed","saved","raised","hunted"],"explanation":"are being hunted 被捕猎。"},{"q":"3","answer":"A","options":["smaller","bigger","louder","richer"],"explanation":"getting smaller 越来越小。"},{"q":"4","answer":"B","options":["prices","spaces","noises","songs"],"explanation":"living spaces 生存空间。"},{"q":"5","answer":"C","options":["sell","lose","adapt","forget"],"explanation":"adapt to 适应。"},{"q":"6","answer":"D","options":["noise","price","weather","pressure"],"explanation":"under pressure 承受压力。"},{"q":"7","answer":"A","options":["buy","make","find","open"],"explanation":"not to buy products 不买制品。"},{"q":"8","answer":"B","options":["danger","safety","trouble","noise"],"explanation":"live in safety 安全地生活。"},{"q":"9","answer":"C","options":["leave","sell","work","fail"],"explanation":"won''t work overnight 不会一夜见效。"},{"q":"10","answer":"D","options":["empty","late","free","important"],"explanation":"just as important 同样重要。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'Off the Danger List', 'For many years, one wild species in China lived under a heavy (1)____ from hunters and from the loss of its home. Things looked very (2)____, and people feared it might soon disappear forever. Then the government placed the animal under national (3)____. Volunteers (4)____ over the herds day and night to keep them safe from attacks. New bridges and gates were (5)____ so that the animals could move about easily and stay away from cars and trains. These (6)____ turned out to be very effective. Year after year, the population slowly began to (7)____, until at last the species was (8)____ from the endangered list. It was wonderful (9)____, but the work did not stop there. The threats had not fully gone, so the protection programmes (10)____ on. The story shows that, with patience and care, even an animal close to extinction can be brought back.', 147, 2, '[{"q":"1","answer":"A","options":["threat","price","noise","holiday"],"explanation":"a heavy threat 沉重威胁。"},{"q":"2","answer":"B","options":["bright","bad","funny","easy"],"explanation":"looked bad 形势糟糕。"},{"q":"3","answer":"C","options":["market","protection","factory","station"],"explanation":"national protection 国家保护。"},{"q":"4","answer":"D","options":["sold","lost","broke","watched"],"explanation":"watched over 看护。"},{"q":"5","answer":"A","options":["added","sold","lost","thrown"],"explanation":"were added 被增设。"},{"q":"6","answer":"B","options":["prices","measures","noises","songs"],"explanation":"these measures 这些措施。"},{"q":"7","answer":"C","options":["fall","leave","recover","die"],"explanation":"begin to recover 开始恢复。"},{"q":"8","answer":"D","options":["bought","lost","broken","removed"],"explanation":"was removed 被移除。"},{"q":"9","answer":"A","options":["news","noise","price","weather"],"explanation":"wonderful news 好消息。"},{"q":"10","answer":"B","options":["broke","went","sold","fell"],"explanation":"went on 继续。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U2', 'The Elephant Whisperers', 'In Kenya, a special group of keepers look after baby elephants that have lost their (1)____. The little animals are brought to a centre, where they are (2)____ milk from bottles every few hours, day and night. The keepers do far (3)____ than just feed them. They sing to the elephants, play games with them, and even (4)____ beside them at night so that the young ones do not feel (5)____. The most important thing each baby must (6)____ is how to live in the wild again. Little by little, the keepers (7)____ the elephants into the forest and teach them to find food on their (8)____. So far, the centre has helped hundreds of orphan elephants (9)____ to a normal life. The keepers say that elephants, like people, need love and patience. Their gentle work (10)____ us that protecting wildlife is not only about laws, but also about kindness.', 150, 2, '[{"q":"1","answer":"C","options":["prices","noises","mothers","tickets"],"explanation":"lost their mothers 失去母亲。"},{"q":"2","answer":"D","options":["sold","thrown","lost","given"],"explanation":"are given milk 被喂奶。"},{"q":"3","answer":"A","options":["more","less","fewer","least"],"explanation":"do more than 不止于。"},{"q":"4","answer":"B","options":["sell","sleep","leave","buy"],"explanation":"sleep beside them 睡在它们旁边。"},{"q":"5","answer":"C","options":["rich","late","alone","busy"],"explanation":"feel alone 感到孤单。"},{"q":"6","answer":"D","options":["lose","sell","forget","learn"],"explanation":"must learn 必须学会。"},{"q":"7","answer":"A","options":["lead","sell","throw","lose"],"explanation":"lead the elephants 带领大象。"},{"q":"8","answer":"B","options":["price","own","noise","song"],"explanation":"on their own 靠自己。"},{"q":"9","answer":"C","options":["fall","leave","return","die"],"explanation":"return to a normal life 回归正常生活。"},{"q":"10","answer":"D","options":["sells","loses","breaks","reminds"],"explanation":"reminds us 提醒我们。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 Concern for the Elephants', '必修二 U2 · dialogue', 3, 'Anna: I''m really concerned about the African elephants these days.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 An Alarming Rate', '必修二 U2 · passage', 2, 'Our planet''s wildlife is dying out at an alarming rate.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 A Weekend of Birdwatching', '必修二 U2 · dialogue', 3, 'Lily: We got up so early this morning to search for wild birds!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 The Tibetan Antelope''s Comeback', '必修二 U2 · passage', 2, 'In the 1980s and 1990s, the Tibetan antelope was in great danger.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 Designing a Poster', '必修二 U2 · dialogue', 3, 'Mia: We need to make a poster about an endangered animal. Where do we start?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 Baby Elephants in Kenya', '必修二 U2 · passage', 2, 'At a centre in Kenya, keepers look after baby elephants that have lost their mothers.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Make a Poster Calling for Wildlife Protection(写一篇呼吁保护野生动物的海报/倡议信)', 'Protect Our Wildlife', '假设你是李华,学校环保社团要为''世界野生动物日''制作一张海报(或一封面向同学的倡议信)。请用英语写约80词的海报内容,包括:① 指出一种濒危动物(如非洲象/藏羚羊)及它为何濒危;② 说明正在采取什么措施(用现在进行时被动语态);③ 呼吁同学们能做些什么(如拒买动物制品)。注意:语气号召、要点清楚。', 'Suppose you are Li Hua. Your school''s environmental club is making a poster (or an open letter to schoolmates) for World Wildlife Day. Write about 80 words including: 1) name one endangered animal and why it is in danger; 2) what is being done to help it (use the present continuous passive voice); 3) call on your schoolmates to take action, such as refusing to buy animal products.', '["点明濒危动物及原因(… is in danger because …)","正在采取的措施(… is being done / measures are being taken)","号召行动(Let''s … / Please do not buy …)","语气号召有力、要点清楚连贯"]'::jsonb, 70, 100, 'Protect Our Wildlife! The African elephant is in great danger. It is being hunted for its tusks, and at the same time its habitat is getting smaller. The good news is that much is being done to help. Special parks are being built, and people are being told not to buy elephant products. But the animals still need us. Please do not buy goods made from wild animals, and share this message with your family and friends. Remember: when the buying stops, the killing can stop too. Change begins with you!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The African elephant is being hunted for its tusks, and its habitat is getting smaller.","Much is being done to help: special parks are being built and people are being told not to buy animal products.","Please do not buy goods made from wild animals.","When the buying stops, the killing can stop too."]'::jsonb, '[{"wrong":"The elephant is being hunt now.","correct":"The elephant is being hunted now.","note":"现在进行被动 = be being + 过去分词,hunt 的过去分词是 hunted。"},{"wrong":"New parks is being built.","correct":"New parks are being built.","note":"复数主语 parks 用 are being built。"},{"wrong":"Please not buy animal products.","correct":"Please do not buy animal products.","note":"否定祈使句用 Please do not / Don''t + 动词原形。"}]'::jsonb, '【野生动物保护海报/倡议信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required2', 'U2', '{"title":"现在进行时的被动语态(is/are being done)速查","intro":"当主语是动作的承受者、且动作此刻正在被进行时,用 am/is/are being + 过去分词,意为''正在被……''。判断口诀:主语挨动作 + 此刻正在发生 → 用 be being done。","table":{"headers":["句型","结构 / 例句"],"rows":[["肯定(单数)","is being + 过去分词:The wetland is being destroyed.(湿地正在被破坏)"],["肯定(复数)","are being + 过去分词:Small birds are being caught.(小鸟正在被捕)"],["否定","isn''t/aren''t being + 过去分词:The trees aren''t being cut down now."],["一般疑问","Is/Are + 主语 + being + 过去分词?:Are the ducks being sold?"],["对照","经常/客观:is done(are served every day);此刻正在:is being done"]]},"specialRules":[{"rule":"结构固定 = be(am/is/are)+ being + 过去分词,being 不变","mark":"are being hunted √ / are hunting ×"},{"rule":"主语单复数决定 be 用 is 还是 are","mark":"The wetland is being… / Birds are being…"},{"rule":"by 短语引出动作执行者(可省略)","mark":"The dolphins are being searched for by volunteers."},{"rule":"区分''正在被做''(is being done)与''经常被做/事实''(is done)","mark":"Shark fins are served daily(惯常)/ being served now(此刻)"}],"why":["现在进行时表示''此刻正在发生'',被动语态表示''主语承受动作'';二者合一就是''某事此刻正在被进行'',所以用 be being + 过去分词。"],"gaokaoPoints":["语法填空高频:给动词原形,需填 is/are being + 过去分词(主谓一致 + 不规则过去分词)。","易错点:漏掉 being(误写成 is hunted)或把进行误判为完成;''每天/经常''类时间状语要用一般现在被动 is done,不是 being done。"],"examVsReal":[{"exam":"A new park is being built.(考试/书面正式)","real":"They''re building a new park.","note":"口语里常用主动进行;被动多见于书面、新闻和说明文"},{"exam":"The river is being cleaned now.(强调过程被动)","real":"Someone''s cleaning the river right now.","note":"日常更爱用 someone / they + 主动,被动显得客观正式"}]}'::jsonb);
